import { createApiClient, HttpError } from './base.js';
import { ClassroomResponseSchema, ClassroomRequestSchema } from '../schemas/classroom.js';
import { PagedResultSchema } from '../schemas/pagedResult.js';
import { buildPageParams } from '../utils/queryUtils.js';

const api = createApiClient({
  baseURL: import.meta.env.VITE_API_URL ?? 'http://localhost:8080',
  headers: { Accept: 'application/json' },
});

function resolveErrorMessage(error, overrides = {}) {
  if (overrides[error.status]) return overrides[error.status];
  const serverMessage = error.data?.message;
  const defaults = {
    0: 'No se pudo conectar con el servidor. Verifica tu conexión.',
    400: serverMessage || 'Los datos enviados no son válidos.',
    401: 'No autorizado.',
    403: 'No tienes permisos para realizar esta acción.',
    404: 'El aula solicitada no existe.',
    500: 'Error interno del servidor. Intenta de nuevo más tarde.',
  };
  return defaults[error.status] || serverMessage || `Error inesperado (${error.status}).`;
}

export async function getClassrooms({ search, page, size, sort, direction } = {}) {
  try {
    const qs = buildPageParams({ search, page, size, sort, direction });
    const { data } = await api.get(`/api/v1/classrooms${qs}`);
    return PagedResultSchema(ClassroomResponseSchema).parse(data.data);
  } catch (error) {
    if (error instanceof HttpError) throw new Error(resolveErrorMessage(error));
    throw error;
  }
}

export async function getClassroom(uuid) {
  try {
    const { data } = await api.get(`/api/v1/classrooms/${uuid}`);
    return ClassroomResponseSchema.parse(data.data ?? data);
  } catch (error) {
    if (error instanceof HttpError) throw new Error(resolveErrorMessage(error));
    throw error;
  }
}

export async function createClassroom(payload) {
  try {
    const body = ClassroomRequestSchema.parse(payload);
    const { data } = await api.post('/api/v1/classrooms', body);
    return ClassroomResponseSchema.parse(data.data ?? data);
  } catch (error) {
    if (error instanceof HttpError) throw new Error(resolveErrorMessage(error));
    throw error;
  }
}

export async function updateClassroom(uuid, payload) {
  try {
    const body = ClassroomRequestSchema.parse(payload);
    const { data } = await api.put(`/api/v1/classrooms/${uuid}`, body);
    return ClassroomResponseSchema.parse(data.data ?? data);
  } catch (error) {
    if (error instanceof HttpError) throw new Error(resolveErrorMessage(error));
    throw error;
  }
}

import { render, screen } from '@testing-library/react';
import { BrowserRouter } from 'react-router-dom';
import Error401 from '../Error401';
import Error403 from '../Error403';
import Error404 from '../Error404';

/**
 * Tests para las pantallas de error
 * Verifica que cada pantalla de error muestre el contenido y links correctos
 */
describe('Error401 - Sesión no válida', () => {
  it('debe mostrar el mensaje de sesión no válida', () => {
    render(
      <BrowserRouter>
        <Error401 />
      </BrowserRouter>
    );

    expect(screen.getByText(/Sesión no válida/i)).toBeInTheDocument();
    expect(screen.getByText(/ERROR 401/)).toBeInTheDocument();
  });

  it('debe mostrar instrucción para iniciar sesión', () => {
    render(
      <BrowserRouter>
        <Error401 />
      </BrowserRouter>
    );

    expect(screen.getByText(/Necesitas iniciar sesión/i)).toBeInTheDocument();
    expect(screen.getByText(/expirado|token/i)).toBeInTheDocument();
  });

  it('debe tener link a /login', () => {
    render(
      <BrowserRouter>
        <Error401 />
      </BrowserRouter>
    );

    const link = screen.getByRole('link', { name: /Ir a iniciar sesión/i });
    expect(link).toHaveAttribute('href', '/login');
  });

  it('debe tener un icono de candado', () => {
    const { container } = render(
      <BrowserRouter>
        <Error401 />
      </BrowserRouter>
    );

    // Verificar que hay un SVG (icono)
    const svg = container.querySelector('svg');
    expect(svg).toBeInTheDocument();
  });
});

describe('Error403 - Acceso denegado', () => {
  it('debe mostrar el mensaje de acceso denegado', () => {
    render(
      <BrowserRouter>
        <Error403 />
      </BrowserRouter>
    );

    expect(screen.getByText(/Acceso denegado/i)).toBeInTheDocument();
    expect(screen.getByText(/ERROR 403/)).toBeInTheDocument();
  });

  it('debe mostrar que el usuario no tiene permisos', () => {
    render(
      <BrowserRouter>
        <Error403 />
      </BrowserRouter>
    );

    expect(screen.getByText(/no tienes permisos/i)).toBeInTheDocument();
    expect(screen.getByText(/modulo|acción/i)).toBeInTheDocument();
  });

  it('debe tener link a /dashboard', () => {
    render(
      <BrowserRouter>
        <Error403 />
      </BrowserRouter>
    );

    const link = screen.getByRole('link', { name: /Volver al dashboard/i });
    expect(link).toHaveAttribute('href', '/dashboard');
  });

  it('debe mostrar icono de escudo', () => {
    const { container } = render(
      <BrowserRouter>
        <Error403 />
      </BrowserRouter>
    );

    // Verificar que hay un SVG (icono de escudo)
    const svg = container.querySelector('svg');
    expect(svg).toBeInTheDocument();
  });
});

describe('Error404 - Página no encontrada', () => {
  it('debe mostrar el mensaje de página no encontrada', () => {
    render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    expect(screen.getByText(/Página no encontrada/i)).toBeInTheDocument();
    expect(screen.getByText(/ERROR 404/)).toBeInTheDocument();
  });

  it('debe mostrar que la ruta no existe', () => {
    render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    expect(screen.getByText(/ruta.*no existe|movida|disponible/i)).toBeInTheDocument();
  });

  it('debe tener link a /dashboard', () => {
    render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    const link = screen.getByRole('link', { name: /Volver al dashboard/i });
    expect(link).toHaveAttribute('href', '/dashboard');
  });

  it('debe tener link a /reservations como opción secundaria', () => {
    render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    const link = screen.getByRole('link', { name: /Ver reservaciones/i });
    expect(link).toHaveAttribute('href', '/reservations');
  });

  it('debe mostrar icono de búsqueda', () => {
    const { container } = render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    // Verificar que hay un SVG (icono)
    const svg = container.querySelector('svg');
    expect(svg).toBeInTheDocument();
  });
});

describe('Comparación visual de errores', () => {
  it('Error401 debe mostrar código 401', () => {
    render(
      <BrowserRouter>
        <Error401 />
      </BrowserRouter>
    );

    expect(screen.getByText(/ERROR 401/)).toBeInTheDocument();
  });

  it('Error403 debe mostrar código 403', () => {
    render(
      <BrowserRouter>
        <Error403 />
      </BrowserRouter>
    );

    expect(screen.getByText(/ERROR 403/)).toBeInTheDocument();
  });

  it('Error404 debe mostrar código 404', () => {
    render(
      <BrowserRouter>
        <Error404 />
      </BrowserRouter>
    );

    expect(screen.getByText(/ERROR 404/)).toBeInTheDocument();
  });
});

